import os, json, csv, shutil, subprocess, sys
from pathlib import Path
from decimal import Decimal, ROUND_HALF_UP
from collections import defaultdict
from openpyxl import load_workbook

params=json.load(open(os.environ['AEP_WORKFLOW_PARAMS'], encoding='utf-8'))
from_date=params['from_date']; to_date=params['to_date']; period=params['period']
base=Path.cwd(); inp=base/'input'; out=base/'output'; downloads=out/'downloads'; downloads.mkdir(parents=True, exist_ok=True)
print('INPUTS', {'workspace': str(base), 'from_date': from_date, 'to_date': to_date, 'period': period})
print('FILES input', sorted(p.name for p in inp.iterdir()) if inp.exists() else [])
print('FILES downloads before', sorted(p.name for p in downloads.iterdir()))

orders_file=downloads/f'sap_orders_{period}.csv'
invoices_file=downloads/f'sap_invoices_{period}.csv'
expenses_file=downloads/f'expenses_{period}_approved.csv'
quotes_file=downloads/f'quotes_{period}_accepted.csv'
outfile=out/f'project_integration_{period}.xlsx'
for p in [orders_file,invoices_file,expenses_file]:
    if not p.exists():
        raise FileNotFoundError(str(p))

# Locate assets
fx_file=inp/'fx_rates.csv'
template=inp/'project_template.xlsx'
if not fx_file.exists(): raise FileNotFoundError(str(fx_file))
if not template.exists(): raise FileNotFoundError(str(template))

# Read CSV helpers
def read_csv(path):
    with open(path, newline='', encoding='utf-8-sig') as f:
        rows=list(csv.DictReader(f))
    print('READ', path.name, 'rows', len(rows), 'headers', list(rows[0].keys()) if rows else [])
    return rows
orders=read_csv(orders_file)
invoices=read_csv(invoices_file)
expenses=read_csv(expenses_file)

# FX rates
fx={}
for r in read_csv(fx_file):
    cur=(r.get('Currency') or r.get('currency') or '').strip()
    val=(r.get('RateToTWD') or r.get('TWD') or r.get('rate') or '').strip()
    if cur and val:
        fx[cur]=Decimal(val)
if 'TWD' not in fx: fx['TWD']=Decimal('1')
print('FX', fx)

def dec(v):
    if v is None or str(v).strip()=='' : return Decimal('0')
    return Decimal(str(v).replace(',','').strip())
def money(v):
    return float(v.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
def get(row,*names):
    lower={k.lower():k for k in row.keys()}
    for n in names:
        if n in row: return row[n]
        if n.lower() in lower: return row[lower[n.lower()]]
    return ''
def amount_twd(row, amount_names=('Amount','Total','TotalAmount','LineAmount')):
    amount=dec(next((get(row,n) for n in amount_names if get(row,n) not in (None,'')), '0'))
    cur=(get(row,'Currency') or 'TWD').strip()
    return amount * fx.get(cur, Decimal('1'))
def project(row): return (get(row,'ProjectID','ProjectId','Project') or '(blank)').strip() or '(blank)'

# Quote CLI: use installed/manual-provided CLI if present
cli_candidates=[]
for name in ['quote_cli.py','quote_cli']:
    cli_candidates += list(inp.rglob(name))
if cli_candidates:
    cli=cli_candidates[0]
    cmd=[sys.executable, str(cli), '--from', from_date, '--to', to_date, '--status', 'Accepted', '--output', str(quotes_file)] if cli.suffix=='.py' else [str(cli), '--from', from_date, '--to', to_date, '--status', 'Accepted', '--output', str(quotes_file)]
    print('RUN quote cli', cmd)
    res=subprocess.run(cmd, cwd=base, text=True, capture_output=True)
    print('quote cli return', res.returncode, 'stdout', res.stdout[-1000:], 'stderr', res.stderr[-1000:])
    if res.returncode!=0:
        raise RuntimeError('quote cli failed')
else:
    # keep existing exported accepted quotes if prior browser/manual step created them
    if not quotes_file.exists():
        raise FileNotFoundError('No quote_cli found and no quotes export exists: '+str(quotes_file))
quotes=read_csv(quotes_file)

summary=defaultdict(lambda: {'orders':Decimal('0'),'invoices':Decimal('0'),'expenses':Decimal('0'),'quotes':Decimal('0')})
for r in orders: summary[project(r)]['orders'] += amount_twd(r)
for r in invoices: summary[project(r)]['invoices'] += amount_twd(r)
for r in expenses: summary[project(r)]['expenses'] += amount_twd(r, ('Amount','Total','ExpenseAmount'))
for r in quotes: summary[project(r)]['quotes'] += amount_twd(r, ('Amount','Total','QuoteAmount'))

shutil.copy2(template, outfile)
wb=load_workbook(outfile)
# Fill first/known sheets conservatively, preserving template
if 'Summary' in wb.sheetnames:
    ws=wb['Summary']
else:
    ws=wb.create_sheet('Summary')
ws.delete_rows(1, ws.max_row)
ws.append(['ProjectID','Orders_TWD','Invoices_TWD','Expenses_TWD','AcceptedQuotes_TWD','Attention'])
for pid in sorted(summary):
    s=summary[pid]
    attention=[]
    if s['expenses'] > s['invoices']: attention.append('Expenses exceed invoices')
    if s['invoices'] > s['orders']: attention.append('Invoices exceed orders')
    ws.append([pid,money(s['orders']),money(s['invoices']),money(s['expenses']),money(s['quotes']),'; '.join(attention)])

def write_detail(sheet, rows):
    if sheet in wb.sheetnames:
        ws=wb[sheet]; ws.delete_rows(1, ws.max_row)
    else:
        ws=wb.create_sheet(sheet)
    headers=list(rows[0].keys()) if rows else []
    ws.append(headers)
    for r in rows: ws.append([r.get(h,'') for h in headers])
write_detail('Orders', orders)
write_detail('Invoices', invoices)
write_detail('Expenses', expenses)
write_detail('Quotes', quotes)
wb.save(outfile)
print('WROTE', outfile)

# Verify saved output
wb2=load_workbook(outfile, data_only=True)
for s in ['Summary','Orders','Invoices','Expenses','Quotes']:
    if s not in wb2.sheetnames: raise AssertionError('missing sheet '+s)
print('CHECK workbook sheets', wb2.sheetnames)
print('CHECK row counts', {'orders':len(orders),'invoices':len(invoices),'expenses':len(expenses),'quotes':len(quotes),'summary_projects':len(summary)})
for p in [orders_file,invoices_file,expenses_file,quotes_file,outfile]:
    print('OUTPUT', p, p.exists(), p.stat().st_size if p.exists() else None)

