projects=[params['expense_project_1'], params['expense_project_2']]
TWOPLACES=Decimal('0.01')
def money(x): return Decimal(str(x)).quantize(TWOPLACES, rounding=ROUND_HALF_UP)
def read_csv(path):
    with open(path, newline='', encoding='utf-8-sig') as f: return list(csv.DictReader(f))
def parse_date(s): return date.fromisoformat(str(s)) if s not in (None,'') else None
rates={}
with open(input_dir/'fx_rates.csv', newline='', encoding='utf-8-sig') as f:
    rdr=csv.reader(f); next(rdr)
    for row in rdr:
        if row and row[0]: rates[row[0]]=Decimal(row[1])
def twd(amount, currency):
    if currency not in rates: raise ValueError(f'Missing FX rate for {currency}')
    return (Decimal(str(amount))*rates[currency]).quantize(TWOPLACES, rounding=ROUND_HALF_UP)
def clear_data(s, min_row=5):
    if s.max_row>=min_row: s.delete_rows(min_row, s.max_row-min_row+1)
