    for i,v in enumerate(values, 1):
        c=s.cell(n,i); c.value=v
        if i in text_cols: c.number_format='@'
        if i in date_cols: c.number_format='yyyy-mm-dd'
        if i in money_cols: c.number_format='0.00'
orders_raw=read_csv(dl_dir/f'orders_{customer}_{from_date}_{to_date}.csv')
invoices_raw=read_csv(dl_dir/f'invoices_{customer}_{from_date}_{to_date}.csv')
orders=[]
for r in orders_raw:
    if r['CustomerID']==customer and from_date<=r['OrderDate']<=to_date and r['Status']!='Cancelled':
        orders.append({'OrderID':r['OrderID'],'ProjectID':r['ProjectID'],'CustomerID':r['CustomerID'],'OrderDate':parse_date(r['OrderDate']),'Status':r['Status'],'Currency':r['Currency'],'NetAmount':money(r['NetAmount']),'AmountTWD':twd(r['NetAmount'],r['Currency'])})
invoices=[]
for r in invoices_raw:
    if r['CustomerID']==customer and from_date<=r['InvoiceDate']<=to_date:
        invoices.append({'InvoiceID':r['InvoiceID'],'OrderID':r['OrderID'],'ProjectID':r['ProjectID'],'CustomerID':r['CustomerID'],'InvoiceDate':parse_date(r['InvoiceDate']),'DueDate':parse_date(r['DueDate']),'Currency':r['Currency'],'Amount':money(r['Amount']),'PaidAmount':money(r['PaidAmount']),'Balance':money(r['Balance']),'BalanceTWD':twd(r['Balance'],r['Currency'])})
