    quotes.append({'QuoteID':r['QuoteID'],'ProjectID':r['ProjectID'],'CustomerID':r['CustomerID'],'QuoteDate':parse_date(r['QuoteDate']),'ValidUntil':parse_date(r['ValidUntil']),'Status':r['Status'],'Currency':r['Currency'],'NetAmount':money(r['NetAmount']),'AmountTWD':twd(r['NetAmount'],r['Currency'])})
