orders.sort(key=lambda r:(r['OrderDate'],r['OrderID'])); invoices.sort(key=lambda r:(r['InvoiceDate'],r['InvoiceID'])); expenses.sort(key=lambda r:(r['ExpenseDate'],r['ExpenseID'])); quotes.sort(key=lambda r:(r['QuoteDate'],r['QuoteID']))
exceptions=[]
