out=out_dir/f'project_report_{customer}_{from_date}_{to_date}_TWD.xlsx'
shutil.copy2(input_dir/'project_template.xlsx', out)
wb=load_workbook(out)
gen=datetime.now().replace(microsecond=0).isoformat()
rep=wb['Report']; rep['B3']=from_date; rep['D3']=to_date; rep['B4']=f'Customer {customer}; orders exclude Cancelled; expenses Approved only for supplied customer-related projects {", ".join(projects)}; quotes all statuses; FX from input/fx_rates.csv.'; rep['B5']=gen; rep['B7']='Lab ERP; Expense Viewer; quote_cli; fx_rates.csv'; rep['D7']=gen; rep['B9']=f'Attention: invoices with DueDate <= {cutoff.isoformat()} and Balance > 0; approved expenses missing receipt; quotes ValidUntil < {cutoff.isoformat()} and Status != Accepted. No live FX used.'
for name in ['Orders','Invoices','Expenses','Quotes','Summary','Exceptions']: clear_data(wb[name],5)
for i,r in enumerate(orders,5): set_row(wb['Orders'],i,[r['OrderID'],r['ProjectID'],r['CustomerID'],r['OrderDate'],r['Status'],r['Currency'],r['NetAmount'],r['AmountTWD']],{1,2,3,5,6},{4},{7,8})
for i,r in enumerate(invoices,5): set_row(wb['Invoices'],i,[r['InvoiceID'],r['OrderID'],r['ProjectID'],r['CustomerID'],r['InvoiceDate'],r['DueDate'],r['Currency'],r['Amount'],r['PaidAmount'],r['Balance'],r['BalanceTWD']],{1,2,3,4,7},{5,6},{8,9,10,11})
for i,r in enumerate(expenses,5): set_row(wb['Expenses'],i,[r['ExpenseID'],r['ProjectID'],r['EmployeeID'],r['ExpenseDate'],r['Status'],r['Currency'],r['Amount'],r['AmountTWD']],{1,2,3,5,6},{4},{7,8})
for i,r in enumerate(quotes,5): set_row(wb['Quotes'],i,[r['QuoteID'],r['ProjectID'],r['CustomerID'],r['QuoteDate'],r['ValidUntil'],r['Status'],r['Currency'],r['NetAmount'],r['AmountTWD']],{1,2,3,6,7},{4,5},{8,9})
summary_projects=sorted(set([r['ProjectID'] for r in orders+invoices+quotes+expenses if r.get('ProjectID')]))
for i,pid in enumerate(summary_projects,5): set_row(wb['Summary'],i,[pid,money(sum((r['AmountTWD'] for r in orders if r['ProjectID']==pid),Decimal('0'))),money(sum((r['BalanceTWD'] for r in invoices if r['ProjectID']==pid),Decimal('0'))),money(sum((r['AmountTWD'] for r in expenses if r['ProjectID']==pid),Decimal('0'))),money(sum((r['AmountTWD'] for r in quotes if r['ProjectID']==pid and r['Status']=='Accepted'),Decimal('0')))],{1},set(),{2,3,4,5})
last=max(5,4+len(summary_projects))
for col in 'BCDE': wb['Summary'][f'{col}2']=f'=SUM({col}5:{col}{last})'; wb['Summary'][f'{col}2'].number_format='0.00'
for i,row in enumerate(exceptions,5): set_row(wb['Exceptions'],i,list(row),{1,2,3,4})
wb.save(out)
# Reopen and check
wb2=load_workbook(out, data_only=False)
counts={n:max(0, wb2[n].max_row-4) for n in ['Orders','Invoices','Expenses','Quotes','Summary','Exceptions']}
assert all(wb2['Orders'].cell(r,5).value!='Cancelled' for r in range(5,wb2['Orders'].max_row+1))
assert all(wb2['Expenses'].cell(r,5).value=='Approved' for r in range(5,wb2['Expenses'].max_row+1))
